import { cn } from '@/lib/utils';

type BrandLogoPath = string | { d: string; evenOdd: true };

export interface BrandLogoData {
  /** customer: Logo / <Name> (symbol and wordmark). press: Logo / Press / <Name> (wordmark). */
  kind: 'customer' | 'press';
  /** Width in the 32-high viewBox (the Figma component width). */
  width: number;
  paths: BrandLogoPath[];
}

