export type BrandLogoName = keyof typeof brandLogos;

const brandLogoNames = Object.keys(brandLogos) as BrandLogoName[];
/** The 12 customer marks, in Figma order. */
const customerLogoNames = brandLogoNames.filter(n => brandLogos[n].kind === 'customer');
/** The 6 press mastheads, in Figma order. */
const pressLogoNames = brandLogoNames.filter(n => brandLogos[n].kind === 'press');

/** Figma height of every mark. */
const BRAND_LOGO_HEIGHT = 32;

export interface BrandLogoProps extends Omit<React.ComponentProps<'svg'>, 'name' | 'height' | 'width'> {
  /** Which mark (the Figma name after `Logo / ` or `Logo / Press / `). */
  name: BrandLogoName;
  /** Height in px; the width follows the aspect ratio. Default 32 (Figma). */
  size?: number;
  /** The accessible name (usually the brand name). Leave it out when the name is already in text: the mark is then decorative. */
  title?: string;
}

/** One sample brand mark as an inline SVG in currentColor. */
function BrandLogo({ name, size = BRAND_LOGO_HEIGHT, title, className, ...props }: BrandLogoProps) {
  const logo: BrandLogoData = brandLogos[name];
  const width = Math.round(((logo.width * size) / BRAND_LOGO_HEIGHT) * 100) / 100;
  const label = title?.trim() ? title : undefined;
  return (
    <svg
      data-slot="brand-logo"
      data-logo={name}
      data-kind={logo.kind}
      xmlns="http://www.w3.org/2000/svg"
      viewBox={`0 0 ${logo.width} ${BRAND_LOGO_HEIGHT}`}
      width={width}
      height={size}
      fill="currentColor"
      focusable="false"
      {...(label ? { role: 'img', 'aria-label': label } : { 'aria-hidden': true })}
      className={cn('block shrink-0', className)}
      {...props}
    >
      {label ? <title>{label}</title> : null}
      {logo.paths.map((p, i) =>
        typeof p === 'string' ? <path key={i} d={p} /> : <path key={i} d={p.d} fillRule="evenodd" clipRule="evenodd" />,
      )}
    </svg>
  );
}

export { BrandLogo, brandLogos, brandLogoNames, customerLogoNames, pressLogoNames, BRAND_LOGO_HEIGHT };
